#stage { --ground:#0E0E0F; --main:#04D6A9; --second:#FFFFFF; --accent:#A7A9AC; color:var(--second); font-synthesis:style; font-family:"Museo-300", var(--sans, system-ui, sans-serif) }
.ground { position:absolute; inset:0; background:var(--ground) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:24px } .words > * { margin:0 }
.line { font-family:"Museo-900", var(--display, var(--sans, system-ui, sans-serif)); font-size:72px; line-height:1.08; font-weight:900; letter-spacing:-.5px }
.kicker { font-family:"Museo-300", var(--sans, system-ui, sans-serif); font-size:40px; line-height:1.2; color:color-mix(in srgb, var(--second) 88%, var(--ground)) }
.lbl { font-family:"Museo-300", var(--sans, system-ui, sans-serif); font-size:26px; letter-spacing:.16em; text-transform:uppercase; color:var(--main) }
.panel-l { position:absolute; left:0; top:0; width:560px; height:100%; overflow:hidden; background:linear-gradient(180deg, color-mix(in srgb, var(--ground) 88%, var(--main)), var(--ground) 55%, color-mix(in srgb, var(--ground) 92%, var(--second))) }
.panel-r { position:absolute; left:560px; top:0; width:520px; height:100%; overflow:hidden; background-color:var(--ground) }
.panel-r .tex { position:absolute; inset:-60px; background-size:cover; background-position:center }
.panel-r .tint { position:absolute; inset:0; background:linear-gradient(180deg, color-mix(in srgb, var(--main) 14%, transparent), transparent 45%, color-mix(in srgb, var(--main) 10%, transparent)) }
.seam { position:absolute; left:558px; top:0; width:2px; height:100%; background:color-mix(in srgb, var(--main) 55%, transparent) }
.chev { position:absolute; inset:0; overflow:visible }
.chev path { fill:none; stroke:color-mix(in srgb, var(--main) 22%, transparent); stroke-width:2 }
.net { position:absolute; left:0; top:0 }
.logo { position:absolute; object-fit:contain }
